import{_ as a,o as n,a as p,b as l}from"./app.C41L12d5.js";const c="/ascendc.github.io/assets/fixpipe_nz2dn.BbjdvGs8.png",N=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵搬出关键特性说明","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/cube_store_key_features"},{"text":"NZ2DN","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/NZ2DN"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/NZ2DN.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/NZ2DN.md","outlineHeaders":[{"level":2,"title":"特性说明","slug":"特性说明","link":"#特性说明"},{"level":2,"title":"特性约束","slug":"特性约束","link":"#特性约束"},{"level":2,"title":"使用示例","slug":"使用示例","link":"#使用示例"}],"lastUpdated":1787050286000}'),e={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/NZ2DN.md"};function i(t,s,r,d,w,_){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>NZ2DN<span id="ZH-CN_TOPIC_0000002550560514"></span></h1><h2 id="特性说明">特性说明<a class="header-anchor" href="#特性说明">​</a></h2><p>矩阵计算的搬出过程中NZ2DN的核心功能体现为，将NZ格式矩阵转化为DN格式矩阵。</p><p>NZ2DN转化过程可以参考以下伪代码：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">int</span><span class="w"> </span><span class="n">h</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">h</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">dnNum</span><span class="p">;</span><span class="w"> </span><span class="n">h</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">src_tmp3_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">src</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">h</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">16</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">src_element</span><span class="p">)</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">srcNzMatrixStride</span><span class="p">;</span>
<span class="w">    </span><span class="n">dst_tmp3_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">dst</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">h</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">dst_element</span><span class="p">)</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">dstDnMatrixStride</span><span class="p">;</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">int</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">ceil</span><span class="p">(</span><span class="n">nSize</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="mi">16</span><span class="p">);</span><span class="w"> </span><span class="n">i</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">src_tmp2_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">src_tmp3_addr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">src_element</span><span class="p">)</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">16</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">srcStride</span><span class="p">;</span>
<span class="w">        </span><span class="n">dst_tmp2_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">dst_tmp3_addr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">dst_element</span><span class="p">)</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">16</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">dstStride</span><span class="p">;</span>
<span class="w">        </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">int</span><span class="w"> </span><span class="n">j</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">j</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="mi">16</span><span class="p">;</span><span class="w"> </span><span class="n">j</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">            </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">16</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">j</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">nSize</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">                </span><span class="n">src_block_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">src_tmp2_addr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">j</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">src_element</span><span class="p">);</span>
<span class="w">                </span><span class="n">dst_block_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">dst_tmp2_addr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">j</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">dst_element</span><span class="p">)</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">dstStride</span><span class="p">;</span>
<span class="w">                </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">int</span><span class="w"> </span><span class="n">k</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">k</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">mSize</span><span class="p">;</span><span class="w"> </span><span class="n">k</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">                    </span><span class="n">src_ele_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">src_block_addr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">k</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">src_element</span><span class="p">)</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">16</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">srcNzC0Stride</span><span class="p">;</span>
<span class="w">                    </span><span class="n">dst_ele_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">dst_block_addr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">k</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">dst_element</span><span class="p">);</span>
<span class="w">                </span><span class="p">}</span>
<span class="w">            </span><span class="p">}</span>
<span class="w">        </span><span class="p">}</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>伪代码使用的参数具体说明如下：</p><ul><li>src表示源操作数搬运的起始地址。</li><li>dst表示目的操作数搬运的起始地址。</li><li>源操作数每个NZ矩阵的起始地址为src_tmp3_addr。</li><li>目的操作数每个DN矩阵的起始地址为dst_tmp3_addr。</li><li>源操作数NZ矩阵以每16列为一组数据，每一组数据的起始地址为src_tmp2_addr。</li><li>目的操作数DN矩阵以每16行为一组数据，每一组数据的起始地址为dst_tmp2_addr。</li><li>在上述源自NZ矩阵的每一组数据中，再以每列元素为一组数据，每一组数据的起始地址为src_block_addr。</li><li>在上述源自DN矩阵的每一组数据中，再以每行元素为一组数据，每一组数据的起始地址为dst_block_addr。</li><li>src_ele_addr为NZ矩阵一列的每个元素的地址，dst_ele_addr为DN矩阵一行的每个元素的地址，二者为一一对应关系，对应完成NZ2DN格式转换。</li></ul><p>以下参数为NZ2DN用户可配置参数，含义取值范围参见<a href="../cube_compute_store/Fixpipe_L0CToGM.html#%E5%8F%82%E6%95%B0%E8%AF%B4%E6%98%8E">Fixpipe搬运参数（FixpipeParamsArch3510）</a>：</p><ul><li>dnNum表示需要做NZ2DN转化的矩阵个数。</li><li>mSize与nSize分别表示矩阵m方向和n方向上的维度。</li><li>srcStride表示源NZ矩阵中相邻Z排布的起始地址之间的间隔，单位为C0_Size。</li><li>dstStride表示目的DN矩阵每一行中的元素个数，单位为element。</li><li>srcNzMatrixStride表示不同源NZ矩阵的起始地址的间隔，单位为C0_Size。</li><li>dstDnMatrixStride表示相邻目的DN矩阵起始地址间的间隔，单位为element。</li><li>srcNzC0Stride表示源矩阵NZ分形相邻行的地址偏移为，单位为C0_Size。</li></ul><h2 id="特性约束">特性约束<a class="header-anchor" href="#特性约束">​</a></h2><ul><li>当开启Channel Split/Channel Merge功能（NZ2NZ）时，此功能不可用。</li><li>当L0C Buffer搬运到Unified Buffer（UB）开启双目标模式时，此功能不可用。</li><li>目标操作数地址之间不能重叠。</li></ul><h2 id="使用示例">使用示例<a class="header-anchor" href="#使用示例">​</a></h2><p>如下图所示，在L0C Buffer中有两个NZ格式的矩阵，每个矩阵N方向上维度为32，M方向上维度为48，经过NZ2DN转换，将数据格式变为右部分所示排布。</p><p><strong>图1</strong> NZ2DN示意图<span id="fig3981319172211"></span></p><p><img src="`+c+'" alt></p><p>对于该场景，可以通过配置intriParams结构体参数实现上图的效果：</p><ul><li>dnNum = 2，表示需要做NZ2DN转化的矩阵个数为2。</li><li>nSize = 32，表示源NZ矩阵在N方向上的大小为32个元素。</li><li>mSize = 48，表示源NZ矩阵在M方向上的大小为48个元素。</li><li>srcStride = 80，表示源NZ矩阵中相邻Z排布的起始地址之间的间隔为80 * C0_Size(C0_Size = 16*sizeof(T)，T为操作数的数据类型)字节。</li><li>dstStride = 80，表示目的DN矩阵每一行中的元素个数为80。</li><li>srcNzMatrixStride = 240，表示不同源NZ矩阵的起始地址的间隔为240 * C0_Size。</li><li>dstDnMatrixStride = 48 * 80，表示相邻目的DN矩阵起始地址间的间隔为48 * 80 =3840个元素，40为间隔行数，80为dstStride （每行的元素个数）。</li><li>srcNzC0Stride = 1：表示源矩阵NZ分形相邻行的地址偏移为1 * C0_Size。</li></ul></article></div>',1)])])}const m=a(e,[["render",i]]);export{N as __pageData,m as default};
